-- AI follow-up questions.
--
-- In conversational mode, a text question can opt into one AI follow-up: when
-- the respondent's answer is thin ("it was ok"), Claude asks a single short
-- probing question before the form moves on.
--
--   questions.ai_follow_up   per-question opt-in (text / long_text only)
--   responses.follow_ups     { "<question id>": { "question": text, "answer": text } }
--                            kept apart from `answers` so aggregation,
--                            validation and value_counts never see it
--
-- The follow-up is generated by a public (unauthenticated) server function, so
-- it must not be an open Claude proxy. The browser first claims a ticket here,
-- which checks the question really opts in, rate-limits by hashed client IP
-- (same header resolution as the one-response-per-respondent trigger) and caps
-- volume per form. The server function then redeems the ticket once, getting
-- the form/question context from the database rather than trusting the client.

-- ── Schema ──────────────────────────────────────────────────────────────────

ALTER TABLE public.questions
  ADD COLUMN ai_follow_up boolean NOT NULL DEFAULT false;

ALTER TABLE public.questions
  ADD CONSTRAINT questions_ai_follow_up_text_only
  CHECK (NOT ai_follow_up OR type IN ('text', 'long_text'));

ALTER TABLE public.responses
  ADD COLUMN follow_ups jsonb;

ALTER TABLE public.responses
  ADD CONSTRAINT responses_follow_ups_shape
  CHECK (
    follow_ups IS NULL
    OR (jsonb_typeof(follow_ups) = 'object' AND octet_length(follow_ups::text) <= 100000)
  );

CREATE TABLE public.ai_follow_up_tickets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  form_id uuid NOT NULL REFERENCES public.forms(id) ON DELETE CASCADE,
  question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,
  ip_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  consumed_at timestamptz
);

CREATE INDEX ai_follow_up_tickets_ip_idx
  ON public.ai_follow_up_tickets (form_id, ip_hash, created_at);
CREATE INDEX ai_follow_up_tickets_form_idx
  ON public.ai_follow_up_tickets (form_id, created_at);

-- Internal bookkeeping: RLS on with no policies, so no client can read it.
ALTER TABLE public.ai_follow_up_tickets ENABLE ROW LEVEL SECURITY;

-- ── Claim ───────────────────────────────────────────────────────────────────

-- Returns a single-use ticket id, or NULL when no follow-up should be asked
-- (question doesn't opt in, form not live, or a limit was hit). NULL is a
-- normal outcome: the respondent simply moves on.
CREATE OR REPLACE FUNCTION public.request_ai_follow_up(p_form_id uuid, p_question_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  client_ip text;
  v_hash text;
  v_id uuid;
BEGIN
  -- The question must opt in, and the form must be live — or the caller must
  -- be able to edit it (so owners can try it on a draft).
  IF NOT EXISTS (
    SELECT 1
    FROM public.questions q
    JOIN public.forms f ON f.id = q.form_id
    WHERE q.id = p_question_id
      AND q.form_id = p_form_id
      AND q.ai_follow_up
      AND (f.status = 'published' OR private.has_role(f.user_id, 'editor'))
  ) THEN
    RETURN NULL;
  END IF;

  client_ip := COALESCE(
    NULLIF(current_setting('request.headers', true)::json->>'cf-connecting-ip', ''),
    NULLIF(btrim(split_part(
      COALESCE(current_setting('request.headers', true)::json->>'x-forwarded-for', ''),
      ',', 1)), ''),
    'unknown'
  );
  v_hash := encode(digest(client_ip, 'sha256'), 'hex');

  -- Per respondent: 10 follow-ups per form per hour.
  IF (
    SELECT COUNT(*) FROM public.ai_follow_up_tickets t
    WHERE t.form_id = p_form_id AND t.ip_hash = v_hash
      AND t.created_at > now() - interval '1 hour'
  ) >= 10 THEN
    RETURN NULL;
  END IF;

  -- Per form: 300 per hour, a hard ceiling on spend for any one form.
  IF (
    SELECT COUNT(*) FROM public.ai_follow_up_tickets t
    WHERE t.form_id = p_form_id AND t.created_at > now() - interval '1 hour'
  ) >= 300 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.ai_follow_up_tickets (form_id, question_id, ip_hash)
  VALUES (p_form_id, p_question_id, v_hash)
  RETURNING id INTO v_id;

  -- Opportunistic GC: tickets only matter for the rate-limit window.
  IF random() < 0.02 THEN
    DELETE FROM public.ai_follow_up_tickets WHERE created_at < now() - interval '1 day';
  END IF;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.request_ai_follow_up(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_ai_follow_up(uuid, uuid) TO anon, authenticated;

-- ── Redeem ──────────────────────────────────────────────────────────────────

-- Called by the server function. Marks the ticket used (once, within 10
-- minutes) and returns the context Claude needs. No row = invalid ticket.
CREATE OR REPLACE FUNCTION public.consume_ai_follow_up(p_ticket uuid)
RETURNS TABLE (form_title text, form_description text, question_label text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  WITH used AS (
    UPDATE public.ai_follow_up_tickets t
    SET consumed_at = now()
    WHERE t.id = p_ticket
      AND t.consumed_at IS NULL
      AND t.created_at > now() - interval '10 minutes'
    RETURNING t.form_id, t.question_id
  )
  SELECT f.title, f.description, q.label
  FROM used u
  JOIN public.forms f ON f.id = u.form_id
  JOIN public.questions q ON q.id = u.question_id AND q.ai_follow_up;
END;
$$;

REVOKE ALL ON FUNCTION public.consume_ai_follow_up(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.consume_ai_follow_up(uuid) TO anon, authenticated;

-- ── Editor save path ────────────────────────────────────────────────────────

-- save_form_editor persists ai_follow_up too. Patch the live definition
-- (which already carries the role-based gate) rather than restating it.
DO $mig$
DECLARE
  def text;
BEGIN
  def := pg_get_functiondef('public.save_form_editor(uuid, jsonb, jsonb)'::regprocedure);

  def := replace(def,
    '      logic = i.logic,
      position = i.position',
    '      logic = i.logic,
      ai_follow_up = i.ai_follow_up,
      position = i.position');

  def := replace(def,
    '                THEN elem->''logic'' ELSE NULL END AS logic,
           (ord - 1)::int AS position',
    '                THEN elem->''logic'' ELSE NULL END AS logic,
           COALESCE((elem->>''ai_follow_up'')::boolean, false)
             AND elem->>''type'' IN (''text'', ''long_text'') AS ai_follow_up,
           (ord - 1)::int AS position');

  def := replace(def,
    'INSERT INTO public.questions (form_id, type, label, options, position, required, logic)',
    'INSERT INTO public.questions (form_id, type, label, options, position, required, logic, ai_follow_up)');

  def := replace(def,
    '         CASE WHEN jsonb_typeof(elem->''logic'') = ''object''
              THEN elem->''logic'' ELSE NULL END
  FROM',
    '         CASE WHEN jsonb_typeof(elem->''logic'') = ''object''
              THEN elem->''logic'' ELSE NULL END,
         COALESCE((elem->>''ai_follow_up'')::boolean, false)
           AND elem->>''type'' IN (''text'', ''long_text'')
  FROM');

  IF position('ai_follow_up = i.ai_follow_up' IN def) = 0
     OR position('AS ai_follow_up' IN def) = 0
     OR position('logic, ai_follow_up)' IN def) = 0
     OR (length(def) - length(replace(def, 'IN (''text'', ''long_text'')', ''))) / length('IN (''text'', ''long_text'')') <> 2
  THEN
    RAISE EXCEPTION 'save_form_editor patch did not apply cleanly';
  END IF;

  EXECUTE def;
END;
$mig$;
